    "type": "git",
    "url": "https://github.com/sinclairzx81/typebox"
  },
  "type": "module",
  "types": "./build/index.d.mts",
  "module": "./build/index.mjs",
  "exports": {
    "./compile": {
      "import": "./build/compile/index.mjs",
      "default": "./build/compile/index.mjs"
    },
    "./error": {
      "import": "./build/error/index.mjs",
      "default": "./build/error/index.mjs"
    },
    "./format": {
      "import": "./build/format/index.mjs",
      "default": "./build/format/index.mjs"
    },
    "./guard": {
      "import": "./build/guard/index.mjs",
      "default": "./build/guard/index.mjs"
    },
    "./schema": {
      "import": "./build/schema/index.mjs",
      "default": "./build/schema/index.mjs"
    },
    "./system": {
      "import": "./build/system/index.mjs",
      "default": "./build/system/index.mjs"
    },
    "./type": {
      "import": "./build/type/index.mjs",
      "default": "./build/type/index.mjs"
    },
    "./value": {
      "import": "./build/value/index.mjs",
      "default": "./build/value/index.mjs"
    },
    ".": {
      "import": "./build/index.mjs",
      "default": "./build/index.mjs"
    }
  },
  "typesVersions": {
    "*": {
      "compile": [
        "./build/compile/index.d.mts"
      ],
      "error": [
        "./build/error/index.d.mts"
      ],
      "format": [
        "./build/format/index.d.mts"
      ],
      "guard": [
        "./build/guard/index.d.mts"
      ],
      "schema": [
        "./build/schema/index.d.mts"
      ],
      "system": [
        "./build/system/index.d.mts"
      ],
      "type": [
        "./build/type/index.d.mts"
      ],
      "value": [
        "./build/value/index.d.mts"
      ],
      ".": [
        "./build/index.d.mts"
      ]
    }
  }
}

{
	"name": "chalk",
	"version": "6.0.0",
	"description": "Terminal string styling done right",
	"license": "MIT",
	"repository": "chalk/chalk",
	"funding": "https://github.com/chalk/chalk?sponsor=1",
	"type": "module",
	"exports": {
		"types": "./source/index.d.ts",
		"default": "./source/index.js"
	},
	"imports": {
		"#ansi-styles": "./source/vendor/ansi-styles/index.js",
		"#supports-color": {
			"node": "./source/vendor/supports-color/index.js",
			"default": "./source/vendor/supports-color/browser.js"
		}
	},
	"sideEffects": false,
	"engines": {
		"node": ">=22"
	},
	"scripts": {
		"test": "xo && c8 ava && tsc --noEmit --types node source/index.d.ts",
		"bench": "matcha benchmark.js"
	},
	"files": [
		"source"
	],
	"keywords": [
		"color",
		"colour",
		"colors",
		"terminal",
		"console",
		"cli",
		"string",
		"ansi",
		"style",
		"styles",
		"tty",
		"formatting",
		"rgb",
		"256",
		"shell",
		"xterm",
		"log",
		"logging",
		"command-line",
		"text"
	],
	"devDependencies": {
		"@types/node": "^26.1.1",
		"ansi-styles": "^6.2.3",
		"ava": "^8.0.1",
		"c8": "^12.0.0",
		"color-convert": "^3.1.3",
		"execa": "^10.0.0",
		"log-update": "^8.0.0",
		"matcha": "^0.7.0",
		"typescript": "^6.0.3",
		"xo": "^4.0.0",
		"yoctodelay": "^2.0.0"
	},
	"xo": [
		{
			"ignores": [
				"source/vendor"
			]
		},
		{
			"rules": {
				"unicorn/prefer-string-slice": "off",
				"@typescript-eslint/consistent-type-imports": "off",
				"@typescript-eslint/consistent-type-exports": "off",
				"@typescript-eslint/consistent-type-definitions": "off",
				"unicorn/expiring-todo-comments": "off",
				"no-warning-comments": "off"
			}
		}
	],
	"c8": {
		"reporter": [
			"text",
			"lcov"
		],
		"exclude": [
			"source/vendor"
		]
	}
}

